SELECT 'four_default_off_columns' AS check_name,CASE WHEN (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='hq_review_sms_preferences' AND column_name IN ('purchase','recharge','refund','verification') AND column_default='false' AND is_nullable='NO')=4 THEN 'READY' ELSE 'MISMATCH' END AS status
UNION ALL SELECT 'category_state_consistency',CASE WHEN NOT EXISTS(SELECT 1 FROM public.hq_review_sms_preferences WHERE enabled<>(purchase OR recharge OR refund OR verification)) THEN 'READY' ELSE 'MISMATCH' END
UNION ALL SELECT 'category_function_access',CASE WHEN has_function_privilege('service_role','public.set_hq_review_sms_categories_v95(text,bigint,boolean,boolean,boolean,boolean)','EXECUTE') AND NOT has_function_privilege('anon','public.set_hq_review_sms_categories_v95(text,bigint,boolean,boolean,boolean,boolean)','EXECUTE') AND NOT has_function_privilege('authenticated','public.set_hq_review_sms_categories_v95(text,bigint,boolean,boolean,boolean,boolean)','EXECUTE') THEN 'READY' ELSE 'MISMATCH' END;
